-- 设置 ObjCfg, SpecialObj 当取到的值为空时，自动生成一个表
local meta_auto_create_table =
{
	__index = function (t, k)
		local v = rawget(t,k)
		if v == nil then
			v = {}
			t[k] = v
			return v
		else
			return v
		end
	end,
}
ObjSpeak.ObjCfg = setmetatable({}, meta_auto_create_table)
ObjSpeak.SpecialObj = setmetatable({}, meta_auto_create_table)

