ObjSpeak.WordList[111] = {Word = "这次计划周详，希望别出岔子！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 3000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = false,ShowHead = false,FramePri = 2,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[112] = {Word = "听说江湖上，出了几个怪人，可别被我遇到~",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 3000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = false,ShowHead = false,FramePri = 2,FollowHost = true,ShowMiddle = false,},}
