ObjSpeak.WordList[659] = {Word = "“红蛭”应该把消息带回扶桑了，为何还未答复。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 3000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = false,ShowHead = false,FramePri = 2,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[660] = {Word = "人間の一瞬などそれらに比べれば瞬きほどのわずかなものであろう。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 3000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = false,ShowHead = false,FramePri = 2,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[661] = {Word = "とんでもない痴れ者で困っておる。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 3000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = false,ShowHead = false,FramePri = 2,FollowHost = true,ShowMiddle = false,},}
