ObjSpeak.WordList[667] = {Word = "陷阱里就躺着两只金钱豹，塞牙缝都不够。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 3000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = false,ShowHead = false,FramePri = 2,FollowHost = true,ShowMiddle = false,},}
