ObjSpeak.WordList[957] = {Word = "太极奥义，在于清修……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 3000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = false,ShowHead = false,FramePri = 2,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[958] = {Word = "师父不收我为徒，我就在这跪一辈子。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 3000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = false,ShowHead = false,FramePri = 2,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[959] = {Word = "记不清第几百次失恋了，今天我要喝个痛快，然后就在这泰山出家，永不还俗！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 3000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = false,ShowHead = false,FramePri = 2,FollowHost = true,ShowMiddle = false,},}
