ObjSpeak.WordList[1340] = {Word = "快来人，抓住这些刺客！",Mode = {ShowChat = true,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 3000,PopMaxTime = 3000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = false,ShowHead = false,FramePri = 2,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1341] = {Word = "……前面说到的，正当是：春有萌芽出土俏，夏有荷花飘飘，秋有树叶被风摇，冬有百草穿孝。四时有常，人情无常。暑去寒来杀人刀，怎比那人心摧残，其势浩浩啊。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 8000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1342] = {Word = "要说这五岳剑派，同气连枝。在他自己看来，自是自成一块，好像这江湖也分得剑派之中、剑派之外；在旁人看来，也是他剑派如何如何。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 8000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1343] = {Word = "须知，这派中无派，怎不怪哉？这天下没个长久的坏，自然也就没个长久的好。门派间的隔阂，怎比那人心间的障碍。明月自照沟渠，偏有那性纯之人，要将心托明月。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 8000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1344] = {Word = "今日有衡山二当家操办洗手大会。人道是缘起掌门交椅之争，又道是当家之人性妒擅忌，也说是权衡利弊妥协之举，连城内小儿都学舌唱曰“洗手洗手，大祸临头。”",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 8000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1345] = {Word = "却不知，他衡山一派自开山立派以来，每有大事，哪次不是以小见大，由内见外？这江湖如流自在走，却不缺那庸碌之辈，见浪花便只寻其顽石，见伏草便只觅其弱茎。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 8000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1346] = {Word = "自不量力的邪魔外道！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 3000,PopMaxTime = 3000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
