ObjSpeak.WordList[1391] = {Word = "一十一年江湖梦，是非成败转瞬空……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1392] = {Word = "醉笑陪君三万场，不诉离殇。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1393] = {Word = "江湖子弟江湖老，你流的血越多，流的泪也就越少……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1394] = {Word = "本公子乃峨眉第一美男子，江湖上赫赫有名的翠鸟紫云！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.OUTBURST_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1395] = {Word = "欲知衡山事，莫问白毛鬼！我便是最受莫大掌门宠爱的衡山第一美男子——白毛鬼莫问！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.OUTBURST_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1396] = {Word = "自从本少爷换了这身衣服，教主看我的眼神就格外邪魅……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.OUTBURST_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1397] = {Word = "江湖四大美男，翠鸟紫云、白毛莫问、邪魅东方……还有我，玉面小玄青！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.OUTBURST_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1398] = {Word = "英雄不怕死亡，英雄只怕寂寞地老去……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1399] = {Word = "笨蛋小虫子，弄丢了我的娃娃，再也不和你玩了！嘤嘤嘤嘤……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1400] = {Word = "小灵子不哭，我们一起去把娃娃找回来。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1401] = {Word = "哼，谁稀罕和你们玩了，我去找小盈子玩儿！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1402] = {Word = "小虫子哥哥真可怜……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1403] = {Word = "大人，您看……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1404] = {Word = "放心吧，我会考虑的。绝不会亏待你。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1405] = {Word = "娘子深得秦淮风韵啊，莫非你也去过那里？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1406] = {Word = "公子见笑了。奴家自小衡山人士，为了讨生活才来这开放之地。偶尔也会思念家乡呀。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1407] = {Word = "蹇眉忧愁的你更美丽呢。赐我一个吻吧。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1408] = {Word = "公子真爱说笑，我可是赌酒娘，不赢过我是没可能的哦。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1409] = {Word = "娘子你别光跟那小白脸说话，也搭理搭理我呀！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1410] = {Word = "我可是为你一掷千金，有家不回啊！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1411] = {Word = "以前常听别人说“寂寞”总觉得不屑，今天我也明白那种滋味了。这么孤苦而绝望，无人诉说，无法可救。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1412] = {Word = "偌大的世界，汹涌的人潮，而想找个说话的人却都没有。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1413] = {Word = "那么多人，随便谁不能说呢？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1414] = {Word = "不行，太多笨蛋了。太多虚假的表情。哪怕是真诚的软弱，背人处的落寞，也能感动到我。而甜腻的娇笑却已让我看得厌烦。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1415] = {Word = "像柔软的茧丝子，滑腻地缠上来，紧得让人喘不过气。听说过绞杀树吗？就是那样，藤条的甜密紧缠，最后把依附的大树勒死。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1416] = {Word = "哎，有句话很适合你呢。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1417] = {Word = "是什么？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1418] = {Word = "众人皆醉我独醒，笑眼迷蒙暗自殇。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1419] = {Word = "哈哈，痛快！没想到能在这福州碰到懂我的人呢！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1420] = {Word = "酒逢知己千杯少！来，喝！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1421] = {Word = "美人儿，你可真漂亮。今儿晚上约了人吗？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1422] = {Word = "这次从关外回来，就想看看你面上的疤痕又深了没有。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1423] = {Word = "嘁，你还是那么啰嗦。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1424] = {Word = "呵呵，关外清苦，寂寞难耐。对着星空喝酒时，除了你我还能想谁？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1425] = {Word = "我？想我上次没一刀把你砍死？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1426] = {Word = "哈哈，那一架真是酣畅淋漓、风云变色。便是立时死了，也死而无憾啊！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1427] = {Word = "嘁，你就是要爽不要命。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1428] = {Word = "人生在世苦其多矣！比起跟你打架喝酒，还有什么乐子哪！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1429] = {Word = "难得回来一趟，咱们再比一次？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1430] = {Word = "我才不舍得呢！万一没控制好，把你打死了，往后我怎么办？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1431] = {Word = "嘁，你就能嘴上贫。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1432] = {Word = "三娘,你怎么才来，我们等你好久了。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1433] = {Word = "衣服太大了，我找人帮我改了一下。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1434] = {Word = "嗯……我看看，不错不错,像极了。掌门这一招偷天换日用得实在是妙极。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1435] = {Word = "那是！咱们掌门可是实打实的五岳之首。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1436] = {Word = "要我说，此计若能一举得成，咱们的好日子可就到了！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1437] = {Word = "哈哈！到时候咱哥几个打头阵的，或许还能捞个堂主什么的过把瘾！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1438] = {Word = "别想那些有的没的，刚才有一个小丫头偷听了咱们的谈话，也不知他们追上了没有。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1439] = {Word = "要不一会咱也过去看看。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1440] = {Word = "嘿嘿嘿，现在走出去，谁也想不到咱们原来是嵩山……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1441] = {Word = "嘘！小声点！没看见周围人来人往的么！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1442] = {Word = "就是！要是坏了掌门的大计！不必掌门动手，我俩先把你给拆喽！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1443] = {Word = "哎哟！！轻点！耳朵要掉啦！！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1444] = {Word = "关老板！把你们店里的药材都给咱包起来！有多少拿多少！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1445] = {Word = "把这些药材都拿走，会不会太多了？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1446] = {Word = "多啥！现在不储备好，等到有急用的时候看你怎么找！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1447] = {Word = "也对。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1448] = {Word = "哼哼，再说了，咱把这药材全垄断了，到时候可就有好戏看了。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1449] = {Word = "啥好戏？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1450] = {Word = "笨！当然是那群人无药可医，含恨而终的好戏！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1451] = {Word = "这青天白日的，莫不是真中了什么邪性？！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1452] = {Word = "这可难说，咱镖局好几趟镖连连失利，这可是从来没有过的事情。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1453] = {Word = "轻点声，莫要让老爷子听见。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1454] = {Word = "平之，现在是何时辰了，怎么还未见到镖车的影子。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1455] = {Word = "父亲，你方才已经问过一次了。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1456] = {Word = "想老夫自建立镖局以来，那些镖不论大小，从未有过失手，如今竟接二连三遇上这种事！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1457] = {Word = "父亲莫急，说不定郑镖头他们一会就到。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1458] = {Word = "这都是这个月的第几趟镖了！老夫能不心急吗！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1459] = {Word = "老爷子，要不要我们派人去探探情况？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1460] = {Word = "算了，还是再等等吧…… ",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1461] = {Word = "老爷子果然老了，若是以前他怎么耐得下心来等。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1462] = {Word = "看来福威镖局这次是着了谁的道了。不然也不会次次都被劫镖。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1463] = {Word = "行了，这话你我说说就算了。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1464] = {Word = "我就不信老爷子看不出来。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1465] = {Word = "偷偷告诉你们，李镖头死前曾提起过，最近几次镖其实是被贼人所劫。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1466] = {Word = "说来听听。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1467] = {Word = "据说劫镖的人都穿着日月神教的衣服……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1468] = {Word = "这……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1469] = {Word = "奴有一段情呀，唱拨拉诸公听\r诸公各位，静呀静静心呀",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1470] = {Word = "让我来，唱一首秦淮景呀\r细细那，道来末，唱拨拉诸公听呀",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1471] = {Word = "秦淮缓缓流呀，盘古到如今\r江南锦绣，金陵风雅情呀",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1472] = {Word = "“瞻园”里，堂阔宇深深呀\r“白鹭洲”，水涟涟，世外桃源呀",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1473] = {Word = "哇呀呀！是谁在背后点了我的穴道！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1474] = {Word = "旁边那两人感觉好凶，老爷我有点害怕……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1475] = {Word = "怕什么，有我在呢！这偌大的福州城，除了林震南，就属你老爷我名号最响亮了。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1476] = {Word = "嗯，奴家敬老爷一杯。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1477] = {Word = "公子无所不知，可晓得妾身姻缘在何方吗？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1478] = {Word = "有缘千里来相会，无缘对面不相识。缘之一字，端看娘子是否有心哪。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1479] = {Word = "嘻嘻……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1480] = {Word = "大隐隐于市，袁老可真叫我们好找啊。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1481] = {Word = "呵呵，我这的情报，可是不便宜呢。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1482] = {Word = "要多少您尽管说，钱不成问题。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1483] = {Word = "用钱就能买到的，怎能当得起贵重二字？你行走江湖这么多年，不可能不知道吧。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1484] = {Word = "这……请袁老明示，需要什么代价？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1485] = {Word = "你们都知道我的规矩，情报只赠有缘人。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1486] = {Word = "难道这次，真要空手而回吗？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1487] = {Word = "来而无往……这可不是我独孤无欢的作派。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1488] = {Word = "想不到已近耄耋之年，还能遇上小弟这忘年交，何其难得。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1489] = {Word = "听君一席话，胜读十年书，自从遇到二位前辈，我深感自己已然多偷得了十年光阴。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1490] = {Word = "十年一聚，人生还有几个十年哪。福州这个流水般的城市，会记住这几把老骨头吗？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1491] = {Word = "想被记住？那你还选福州聚会！这个漂浮摇晃、水性杨花的地方，怎么可能指望？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1492] = {Word = "我就随便感慨一下，你当什么真！真想被记住，当初就不会踏进江湖，又要隐形埋名了。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1493] = {Word = "呵呵，铁打的福州，流水的过客。一个没有记忆的城市，一个只有背叛和遗忘的江湖。不看透这些，哪能笑傲呢？两老是这个意思吧。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1494] = {Word = "哈哈哈！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
