ObjSpeak.WordList[1504] = {Word = "人们都说，商人重利轻别离。可若不是小莲和京城的富商一去不回……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
