ObjSpeak.WordList[1511] = {Word = "超弹超Q的章鱼小丸子，高蛋白低脂肪，最佳减肥食品！正宗地道，只此一家~~",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1512] = {Word = "福州特色鲜虾面，一碗只要十文钱！走过路过不要错过~~",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1513] = {Word = "人们都说：这里是个萍水相逢，发生一段奇遇，然后永久怀念的地方。看来当真不假啊！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1514] = {Word = "福州真是个自由的好去处!想说啥就说啥,不怕有人抓,哈哈哈!",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 1000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1515] = {Word = "等这么多天连个鬼影都不见，老子拿命来博，居然还被这些死麻雀拉了一身屎，呸~落嘴里了。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1516] = {Word = "“挽春楼”小月那婊子不错啊，只要给银子她什么都愿意做，今儿要有赚，晚上我就去找她。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1517] = {Word = "小声点，好像有水鱼送上门来了，等下按计划，我从后面包抄，三儿从正面拦住镖车。三儿？三儿死哪里去了？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1518] = {Word = "小月？我横行“挽春楼”多年，怎么不知道“挽春楼”有个叫小月的姑娘？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1519] = {Word = "他不是上次按你的计划，被八匹马的镖车撞下山崖了，什么记性。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1520] = {Word = "听闻“挽春楼”有个洗碗的伙计叫小岳，经常会冒充姑娘灌醉了客人，然后财色兼收……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1521] = {Word = "最近镖行的生意是不是很差，他们生意差，我们也得跟着挨饿，什么世道！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1522] = {Word = "官府的人是不是在搜查我们，听说他们放话说要见一个杀一个，真是残忍。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1523] = {Word = "当年我就说漕运有发展，我们一早就该去做水贼，困在这鸟不拉屎的地方。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1524] = {Word = "我昨天还看见你的悬赏，听说杀了你，可以去官府领五枚铜板。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1525] = {Word = "听说隔壁山头鸟就多，同行说，不注意点儿，说句话鸟屎都能落到口里。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1526] = {Word = "这不到两根油条的价钱，看来是官府想给你改过自新的机会。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1527] = {Word = "林家镖局的事不知道你们都听说了没？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1528] = {Word = "我们这一路从河北到江西，说远不远，说近不近，大家把镖都盯紧了！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1529] = {Word = "你是说林家被青城派咔嚓的事？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1530] = {Word = "不就几箱破布料，山贼抢去穿都觉得寒酸。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1531] = {Word = "怎么从你嘴里说出来，就像是林家人要去做太监的感觉。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1532] = {Word = "你懂个球，这是西域运来的“古池布”和“爱欧微绸缎“，听说价值连城！！！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1533] = {Word = "今夜不如我们就在此地歇脚。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1534] = {Word = "那些山贼早就盯上我怀中这镖儿，我一定会誓死将此镖儿送抵，不然儿……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1535] = {Word = "师弟儿，我们既是同一师门出生又是同一家镖局做事儿，你能不能成熟点儿，稳重点儿。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1536] = {Word = "此地夜风寒冷，晚上师哥你可不要踢被子。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1537] = {Word = "我不准你说！！不准你说这种伤害自己的话儿。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1538] = {Word = "嗯~~~~~人家儿哪里不稳重，人家儿该成熟的都成熟了。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1539] = {Word = "姑娘现在看都不愿多看我一眼，难道你忘了鹧鸪江边，我们发生的那件事！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1540] = {Word = "携手渡江会携出你肚子的孩子？难道我不是孩子的爹！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1541] = {Word = "都说你这娘们儿无情，今日你非得回去跟我成亲不可！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1542] = {Word = "哥哥可不要乱说，咱俩不过是携手渡江，哪有什么事……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1543] = {Word = "大家都是江湖儿女，不妨直言，没个千八百的你还指望当爹，我这就去找个有钱的水鱼嫁给你看。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1544] = {Word = "成你个大头佛，今日老娘就嫁给许家那傻少爷，金银珠宝应有尽有。让我和你回乡下拣牛粪，死龙套，你真当你是有钱NPC啊！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1545] = {Word = "师妹你一个人上路始终不安全，天寒地冻的让我帮你暖个被窝也好。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1546] = {Word = "为什么人家令狐冲的小师妹什么都愿意为他做，你什么都不愿意。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1547] = {Word = "江湖传闻最近东瀛入侵不少流寇，不少镖局的人都遭到了毒手。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1548] = {Word = "如此炎热的三伏天，你居然能找出暖被窝这种借口，懒得和你说，去前方驿站帮我买碗凉茶回来。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1549] = {Word = "人家令狐冲还是笑傲江湖的主角，你就是一龙套，等下放工还要去领盒饭，大家现实一点好吗？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1550] = {Word = "话虽这么说，不过你我二人二十四小时定格在此地，又被制作人鹏哥设定为不可攻击，应该不会出什么事~",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1551] = {Word = "上次给爹写的信，不知他收到没有，听闻他在京城当了个大官。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1552] = {Word = "我只是来借贵宝地歇个脚，讨口茶水，诸位请行个方便。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1553] = {Word = "上月镖局从西域运回的绸缎真是上上品，可惜如此价格只有皇亲国戚能消受得起。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
