ObjSpeak.WordList[1555] = {Word = "戚少爷的“迷云龙玉佩”若是失镖，敢问这镖局可有人能赔得起。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 4000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
