ObjSpeak.WordList[1593] = {Word = "地图若是假的也就罢了，若是真的，又被歹人抢先找到秘洞的话，那就大大不妙了！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
