ObjSpeak.WordList[1595] = {Word = "阿弥陀佛，善哉善哉！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1596] = {Word = "这几张残画出现的太过巧合，剑魔秘洞几百年来踪影全无，为何一下子就冒出来了。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1597] = {Word = "剑魔威名，远播塞外！据传这四张残画是孤剑村村长临死前透露的！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1598] = {Word = "我们十大门派齐聚福州，不就是为了找到剑魔秘洞吗？这些残画无论真假，都要找到，绝不能被人抢先！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1599] = {Word = "孤剑村人乃剑魔之后，此事到也不是谣传，据我看，剑魔秘洞一定在福州城郊！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1600] = {Word = "说那么多废话干嘛，找齐四张残画后，直接去剑魔洞看看不就知道真假了吗？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1601] = {Word = "诸位稍安勿躁，此事应当从长计议，万万不可中了歹人的奸计！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1602] = {Word = "好笑！好笑！这些残画一眼看出就是假的！我倒是要看看谁在后面搞的鬼！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.OUTBURST_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1603] = {Word = "你们中原人最喜欢骗人！连一张地图也搞出这么多花样！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.OUTBURST_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1604] = {Word = "真亦假来假亦真，这里面的真假谁能说的清呢？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.OUTBURST_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1605] = {Word = "老夫倒是不怕有什么阴谋，只是想看看剑魔秘洞中是不是真有什么上古绝学！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.OUTBURST_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1606] = {Word = "在有些特别的箱子中，能找到专门对付贼人的工具。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1607] = {Word = "抓到贼人后，可以把它交到我这里来。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = false,ShowPop = true,PopMinTime = 2000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1608] = {Word = "瞧一瞧看一看，刺虎楼海量花红悬赏缉拿惯盗，想发财的切勿错过啦~",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 1000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1609] = {Word = "缉拿一个惯盗拿他信物就能换那么多钱？果然是个发财的好机会。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 1000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1610] = {Word = "得了吧，既是惯盗哪个手底没有十数条人命，就咱这样的去还不是白给。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 1000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1611] = {Word = "说得也是，如果那么好赚干脆自己赚了，哪还用张榜把银子便宜他人。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 1000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1612] = {Word = "嵩山奸贼，用下毒这种卑鄙手段……看我不把你们千刀万剐！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1613] = {Word = "别吼了，有那点体力不如赶紧运功排毒。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1614] = {Word = "掐指一算，会有一位侠士，在一个万分危险的情况下，披着金甲、踩着凌波微步来救我。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1615] = {Word = "跟这逍遥花痴一起死在这里，莫非我衡山派气数已尽。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1616] = {Word = "月头一出照壁来，不知老妹赶早来。晓得老妹赶早来，涯就骑马扛轿来。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1617] = {Word = "月头一出照壁来，不识哥哥赶早来。识得哥哥赶早来，敲锣打鼓接前来。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1618] = {Word = "唱只添来唱只添，唱到老妹心尖尖。白云作证歌做媒，唱到月头落西天。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1619] = {Word = "唱只添来唱只添，唱到哥哥意绵绵。大山有情妹有福，唱到花好月光圆。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1620] = {Word = "入山看见藤缠树，出山看见树缠藤；藤生树死缠到死，树生藤死死也缠。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1621] = {Word = "连就连，我俩结交订百年；哪个九十七岁死，奈何桥上等三年。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1622] = {Word = "竹子当收你不收，笋子当留你不留，绣球当捡你不捡，空留两手捡忧愁。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1623] = {Word = "新打戒指九连环，一个连环交九年；九九还归八十一，还爱相交十九年。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1624] = {Word = "新搭竹棚种苦瓜，苦瓜结籽在棚下；妹要恋郎快开口，莫作杨梅暗开花。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1625] = {Word = "一树杨梅半树红，你做男人胆要雄；只有男人先开口，女人开口会脸红。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1626] = {Word = "深山大树好遮荫，只听山歌唔见人；妹若有情应一句，省得阿哥满岭寻。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1627] = {Word = "岭岗顶上一株梅，手攀梅树望郎来；阿妈问涯往脉介，涯望梅花几时开。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1628] = {Word = "见妹挑担百二三，阿哥心头着一惊；心想同你分多少，又见人多唔敢声。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1629] = {Word = "花生好食泥里生，泥里生根泥里分；表面开花暗结籽，哥妹相恋莫扬声。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1630] = {Word = "山上天边一朵云，老妹的好真难寻；这个老妹恋得到，死到阴间会还魂。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1631] = {Word = "榄树开花花揽花，阿哥榄上妹榄下；牵起衫尾等郎榄，等郎一榄就归家。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
