ObjSpeak.WordList[1643] = {Word = "唱支山歌分哥听，歌声赛过俏百灵。只要哥哥有本事，那山唱来这山听。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1644] = {Word = "橄榄好食核唔圆，相思唔敢乱开言；哑子食着单只筷，心想成双口难言。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1645] = {Word = "郎有心来妹有心，铁杵磨成绣花针；郎系针来妹系线，针行三步线来寻。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1646] = {Word = "哥系绿叶妹系花，哥系绫罗妹系纱；哥系高山石崖水，妹系山中嫩细茶。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1647] = {Word = "河边杨柳嫩娇娇，拿起浆板等东潮；阿哥摇船妹泼水，船浮水面任哥摇。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1648] = {Word = "咦，怎么有的没有爆炸，该死的奸商！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 1,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
