ObjSpeak.WordList[1695] = {Word = "这个刘正风，犹犹豫豫，又想保全家人，又不肯和魔教划清界限，真是……他是天秤座的么？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1696] = {Word = "有位高人说过，少数人对少数人的暴力是犯罪，多数人对少数人的暴力就会演变成为正义。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1697] = {Word = "刘正风，你勾结魔教、是非不分，如今若是在武林朋友面前低头认罪，随我面见左盟主，或可免你一死！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1698] = {Word = "我与曲洋兄弟以音律相知，已决心退出江湖、不问是非恩怨！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1699] = {Word = "笑话！自古正邪不两立，因为丝竹玩物就与魔教同流合污，正义之士的血都白流了么！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1700] = {Word = "你……你不要欺人太甚！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1701] = {Word = "哼，杀你几个弟子怎么了，一会让你见识见识更狠的……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1702] = {Word = "醉了吧你！哈哈哈，石像和人都分不清了，敢跟老头子我比酒力~！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = false,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1703] = {Word = "醉知酒浓，醒知梦空。倾尽我心，也画不出她那日在月下的惊鸿一舞。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1704] = {Word = "他日若再见夏不语，只叹天不怜我，今生无缘，此恨不关风与月。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 6000,PopMaxTime = 6000,FrameType = ObjSpeak.PopFrame.MENTAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1705] = {Word = "大河向东流啊，这里的NPC解大手啊！诶黑诶黑解大手啊，别人打架我解手啊！解不出来用铁钩啊，钩得屁股满血流啊！风风火火解大手啊……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1706] = {Word = "你就不能消停点吗？这种时候也在闹腾，我们可是强盗！要来这里抢夺五霸岗群雄的宝物的。可以你看看，关键时候，你却在……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1707] = {Word = "对哦，小瘦，快点把裤子脱了。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1708] = {Word = "你要……干嘛？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1709] = {Word = "别想歪了，我只是没带草纸，你裤子的布料看起来也不错。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1710] = {Word = "别这样，会让旁人误会的。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1711] = {Word = "快点脱！你知道，我的钩法可是很厉害的，我可以用钩子瞄准你的脑袋，却钩爆你的蛋蛋！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1712] = {Word = "嗨，啾啾，你想看我在京城的盖的房子吗？叫做鸟巢。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1713] = {Word = "啾啾你怎么不搭理我？你知道吗？“在天愿为比翼鸟”，说的就是我们。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1714] = {Word = "“傻样”",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1715] = {Word = "走，随我去京城吧！这里是块鸟不拉屎的地方，你看我都憋好几天了！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1716] = {Word = "“我不去京城，京城的皇帝都喜欢“鸟生鱼汤”，会把我们杀来吃的。”",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1717] = {Word = "你听错了，是“鸟胜鱼汤”，说的是那些皇帝老儿喜欢我们，胜过喝鱼汤。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1718] = {Word = "恺恺，你真逗！可是它们都说，你不是什么好鸟！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1719] = {Word = "来，啾啾，亲一个！怎么了……为什么躲开？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1720] = {Word = "你的嘴太尖了，刺痛我了……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1721] = {Word = "恺恺，跟你飞的话，那我们就是夫妻了，可是你会说情话吗？",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1722] = {Word = "当然会说，这个我最擅长。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1723] = {Word = "那你说两句听听。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1724] = {Word = "枪打出头鸟。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1725] = {Word = "太不吉利了，换个。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1726] = {Word = "“夫妻本是同命鸟，大难临头……”干嘛！别打头啊，我鸟毛掉了好几个根了，发饰都乱了。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 5000,PopMaxTime = 5000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1727] = {Word = "这宝库之中自有玄机，每隔30秒会出现一些宝箱，其中2只与众不同，打碎可获得财宝，各位需仔细查看。若打碎错误箱子则会引来盗宝贼人。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 8000,PopMaxTime = 8000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1728] = {Word = "看那位大侠，武功好生了得，连打数十回合，竟无一招失手。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1729] = {Word = "红衣的侠士，英武俊俏，待战后定要与他去附近酒楼喝上一杯。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1730] = {Word = "这比武究竟何时才结束，家中还烧着一锅水呢。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1731] = {Word = "下次一定要带家里那怂小子来看看，整日玩弄那些鹌鹑蛐蛐真丢脸。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1732] = {Word = "苦战已经数个时辰了，在门外摆些茶水应该能赚一笔。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1733] = {Word = "这一刀使得好啊！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1734] = {Word = "常闻华山派武功俊朗飘逸，果然名不虚传！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1735] = {Word = "那个逍遥派的！你没事扭什么秧歌，赶紧上去打啊！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1736] = {Word = "少林武学稳重敦厚，只是手中棍子貌似有些粗了，使起来略显费力。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1737] = {Word = "武当剑法飘忽不定，以柔克刚，一把巨剑扛在手中尤其虎虎生风。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1738] = {Word = "从西安前往京师探亲，路过洛阳，不想竟遇到这等壮观场面。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1739] = {Word = "你看那边那厮，发招虽快却无一招命中，可笑，可笑！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1740] = {Word = "腾空，遁地，隐身，中华武学博大精深！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1741] = {Word = "这一招狠啊！打得那人找不到北！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1742] = {Word = "那个逍遥派，就知道扭啊扭啊扭，真是不比从前名望了，净搞些歪门邪道。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1743] = {Word = "那位衡山派的小哥真是招招潇洒自如，英勇无比啊。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1744] = {Word = "这一仗怕是要打到太阳落山咯。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1745] = {Word = "喂，那边的赶紧上啊！老子还赌了石碇银子呢！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1746] = {Word = "武当派那简直就是用那把大剑砸死人啊……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1747] = {Word = "日月神教的招式果然招招阴狠毒辣。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1748] = {Word = "看那边那位女侠，真可谓巾帼英雄，虽衣不蔽体，但也勇闯战场。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1749] = {Word = "风萧萧兮易水寒，壮士一去兮不复还。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1750] = {Word = "打得如此激烈，真怕突然飞出一把刀来伤着自己。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1751] = {Word = "快快打完吧，我好回家吃饭。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1752] = {Word = "五仙教打起架来真是可怕，各种恶心的虫子乱飞。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1753] = {Word = "本打算去武当习武，这么看来，还是去华山吧，剑轻点……",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1754] = {Word = "蜀中唐门可真是帅气非凡，极具视觉冲击力啊。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1755] = {Word = "看得人神经亢奋，真相进去也试一试手！",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1756] = {Word = "这比了许久，不知第一名的奖赏是什么，想来一定丰厚。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1757] = {Word = "有侠士口渴吗，我这里有刚沏好的茶水，来喝一碗吧。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1758] = {Word = "若是这些人能把功夫用到正处，大明朝何来那些内忧外患。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1759] = {Word = "这场上的妹子可真硬朗，一点腰身都看不出来。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1760] = {Word = "这华山派的功夫怎么有些怪异，与从前所见不大一样。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
ObjSpeak.WordList[1761] = {Word = "若是福威镖局的林家还健在，不知在这比斗中胜算几何。",Mode = {ShowChat = false,ChatChannel = CHAT_CHANNEL_LOCAL,ShowSendName = true,ShowPop = true,PopMinTime = 10000,PopMaxTime = 10000,FrameType = ObjSpeak.PopFrame.NORMAL_FRAME,FontName = 0,FontSize = 10,FadePlay = true,ScalePlay = true,ShowHead = true,FramePri = 1,FollowHost = true,ShowMiddle = false,},}
